// Platform seams for iPhone, iPad and Mac. PARENT-OWNED M0 contract: workers use these and
// do not edit this file; ask the parent for additions.
//
// Feature code calls these instead of UIKit or AppKit directly, so one SwiftUI codebase builds
// for both iOS and macOS. For display scale, read SwiftUI's `@Environment(\.displayScale)` in the
// view and pass it down; there is deliberately no global scale lookup. Platform-only features
// (camera scanning, the UIKit share sheet) are gated with `#if os(iOS)` at their call sites.
import SwiftUI

#if os(iOS)
import UIKit

typealias PlatformImage = UIImage
typealias PlatformColor = UIColor
#elseif os(macOS)
import AppKit

typealias PlatformImage = NSImage
typealias PlatformColor = NSColor
#endif

extension Image {
    /// `Image(uiImage:)` on iOS, `Image(nsImage:)` on macOS.
    init(platformImage: PlatformImage) {
        #if os(iOS)
        self.init(uiImage: platformImage)
        #else
        self.init(nsImage: platformImage)
        #endif
    }
}

enum PlatformImageCoding {
    /// Decodes image data (JPEG, PNG, HEIC). Creating the image does not fully validate pixels;
    /// a non-nil result can still lack a decodable bitmap (check `cgImage`).
    static func image(data: Data) -> PlatformImage? {
        PlatformImage(data: data)
    }

    /// JPEG encoding at `quality` (0...1). JPEG has no alpha: transparent pixels are flattened.
    /// Orientation: the result is upright pixels (`UIImage` normalises EXIF orientation when
    /// drawing; callers that need exact EXIF handling decode through ImageIO in `PhotoResizer`).
    static func jpegData(_ image: PlatformImage, quality: CGFloat) -> Data? {
        #if os(iOS)
        return image.jpegData(compressionQuality: quality)
        #else
        guard let cgImage = cgImage(image) else { return nil }
        let rep = NSBitmapImageRep(cgImage: cgImage)
        return rep.representation(using: .jpeg, properties: [.compressionFactor: quality])
        #endif
    }

    /// The underlying bitmap, when there is one.
    static func cgImage(_ image: PlatformImage) -> CGImage? {
        #if os(iOS)
        return image.cgImage
        #else
        var rect = CGRect(origin: .zero, size: image.size)
        return image.cgImage(forProposedRect: &rect, context: nil, hints: nil)
        #endif
    }

    /// Wraps a bitmap. `scale` is the point-to-pixel ratio (iOS semantics).
    static func image(cgImage: CGImage, scale: CGFloat = 1) -> PlatformImage {
        #if os(iOS)
        return UIImage(cgImage: cgImage, scale: scale, orientation: .up)
        #else
        let size = CGSize(width: CGFloat(cgImage.width) / scale, height: CGFloat(cgImage.height) / scale)
        return NSImage(cgImage: cgImage, size: size)
        #endif
    }

    /// Size in pixels (never points). `nil` when the image has no bitmap representation.
    static func pixelSize(_ image: PlatformImage) -> CGSize? {
        if let cgImage = cgImage(image) {
            return CGSize(width: cgImage.width, height: cgImage.height)
        }
        #if os(iOS)
        guard image.scale > 0 else { return nil }
        return CGSize(width: image.size.width * image.scale, height: image.size.height * image.scale)
        #else
        var largest: CGSize?
        for rep in image.representations where rep.pixelsWide > 0 && rep.pixelsHigh > 0 {
            let size = CGSize(width: CGFloat(rep.pixelsWide), height: CGFloat(rep.pixelsHigh))
            if let current = largest, current.width * current.height >= size.width * size.height { continue }
            largest = size
        }
        return largest
        #endif
    }
}

enum Pasteboard {
    /// Replaces the general pasteboard contents with `string`.
    @MainActor static func copy(_ string: String) {
        #if os(iOS)
        UIPasteboard.general.string = string
        #else
        NSPasteboard.general.clearContents()
        NSPasteboard.general.setString(string, forType: .string)
        #endif
    }
}

extension PlatformColor {
    /// A colour that resolves per light or dark appearance.
    static func dynamic(light: PlatformColor, dark: PlatformColor) -> PlatformColor {
        #if os(iOS)
        return UIColor { traits in traits.userInterfaceStyle == .dark ? dark : light }
        #else
        return NSColor(name: nil) { appearance in
            appearance.bestMatch(from: [.darkAqua, .aqua]) == .darkAqua ? dark : light
        }
        #endif
    }
}

enum PlatformSettings {
    /// Where to send someone to change this app's notification permission. Best effort: the
    /// macOS URL opens System Settings > Notifications, which may not select this app.
    static var notificationSettingsURL: URL? {
        #if os(iOS)
        return URL(string: UIApplication.openNotificationSettingsURLString)
        #else
        return URL(string: "x-apple.systempreferences:com.apple.Notifications-Settings.extension")
        #endif
    }
}

enum PlatformLifecycle {
    /// Posted when the app returns to the foreground (iOS) or becomes active (macOS). On macOS
    /// this also fires on ordinary focus changes between apps; handlers must be idempotent.
    static var willEnterForeground: Notification.Name {
        #if os(iOS)
        return UIApplication.willEnterForegroundNotification
        #else
        return NSApplication.willBecomeActiveNotification
        #endif
    }
}

enum PlatformCapabilities {
    /// Live camera barcode and packet capture (AVFoundation) ships on iPhone and iPad only.
    static var supportsCameraScanning: Bool {
        #if os(iOS)
        return true
        #else
        return false
        #endif
    }

    /// True when running the macOS build.
    static var isMac: Bool {
        #if os(macOS)
        return true
        #else
        return false
        #endif
    }
}
